    ('55da0a74-b7fc-4b66-a104-e6b32df0e8e3'::uuid, 'period_name', '4500 - 3000 BC', '< 4500 BC', 'fields-wd5-2026-10-25p-s004-rollback:55da0a74-b7fc-4b66-a104-e6b32df0e8e3:period_name', 'rollback of fields-wd5-2026-10-25p-s004: period_name ''< 4500 BC'' restored on Ballochmyle Cup and Ring marks', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4000) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0110)", "decision": "replace", "status": "MISSING", "reasoning": "The Scottish Archaeological Research Framework case study (written by the AOC survey''s author) calls the Ballochmyle rock art itself Neolithic. AOC and Dig It say only that cup-and-ring marks ''typically'' date to the Bronze Age (c. 2500-700 BC) as a class, and Wikipedia gives Neolithic to Bronze Age (c. 4000-1500 BC) for the art in general; neither rejects a Neolithic start, so the stored -10000 (a rule''s epoch edge, before 4500 BC) has no source and the named period replaces it.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0007", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "SCARF calls the Ballochmyle art Neolithic, but AOC Archaeology (which surveyed the site in 2015) says cup and ring marks typically date to the Bronze Age (c. 2500-700 BC), Atlas Obscura and Wikipedia give 4000-1500 BC for the class, and no direct dating exists, so -4000 as the start of this site is not established.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('55da0a74-b7fc-4b66-a104-e6b32df0e8e3'::uuid, 'period_start', '-4000', '-10000', 'fields-wd5-2026-10-25p-s004-rollback:55da0a74-b7fc-4b66-a104-e6b32df0e8e3:period_start', 'rollback of fields-wd5-2026-10-25p-s004: period_start ''-10000'' restored on Ballochmyle Cup and Ring marks', '[{"source": "https://scarf.scot/thematic/future-thinking-on-carved-stones-in-scotland/future-thinking-on-carved-stones-in-scotland-case-studies/case-study-creative-archaeological-visualization-of-the-rock-art-at-ballochmyle/", "url": "https://scarf.scot/thematic/future-thinking-on-carved-stones-in-scotland/future-thinking-on-carved-stones-in-scotland-case-studies/case-study-creative-archaeological-visualization-of-the-rock-art-at-ballochmyle/", "quote": "The spectacular Neolithic rock art at Ballochmyle extends over three vertical panels on a cliff face overlooking a tributary stream of the River Ayr.", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0110)", "decision": "replace", "status": "MISSING", "reasoning": "The Scottish Archaeological Research Framework case study (written by the AOC survey''s author) calls the Ballochmyle rock art itself Neolithic. AOC and Dig It say only that cup-and-ring marks ''typically'' date to the Bronze Age (c. 2500-700 BC) as a class, and Wikipedia gives Neolithic to Bronze Age (c. 4000-1500 BC) for the art in general; neither rejects a Neolithic start, so the stored -10000 (a rule''s epoch edge, before 4500 BC) has no source and the named period replaces it.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0007", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "SCARF calls the Ballochmyle art Neolithic, but AOC Archaeology (which surveyed the site in 2015) says cup and ring marks typically date to the Bronze Age (c. 2500-700 BC), Atlas Obscura and Wikipedia give 4000-1500 BC for the class, and no direct dating exists, so -4000 as the start of this site is not established.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('56ba3b1c-2d33-465b-b4d0-85fb987fbdc2'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd5-2026-10-25p-s004-rollback:56ba3b1c-2d33-465b-b4d0-85fb987fbdc2:period_name', 'rollback of fields-wd5-2026-10-25p-s004: period_name ''1500 - 500 BC'' restored on Carmona, Spain', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2550) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0119)", "decision": "replace", "status": "MISSING", "reasoning": "The history article on Carmona (English and Spanish versions) dates the first settlement within the limits of the present town to about 4500 years ago, in the full Chalcolithic (1950 minus 4500 = -2550), with Chalcolithic remains at the Alcazar, Barranquillo and Picacho; the Museo de la Ciudad de Carmona likewise begins the town''s story in the Chalcolithic. The mid-8th century BC date of the stored -800 only marks the later ''stable core population'' of the Tartessian period, not the start. -2550 lies in the 3000 - 1500 BC bucket, not the stored 1500 - 500 BC. The Spanish article on the town also says ''more than 5000 years'', a looser statement for the area; the specific figure for the town itself is used.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0007", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "The history article is internally inconsistent (first settlement about 4500 years ago in the body, nearly five thousand years of continuous occupation in the lead) and the Museo de la Ciudad de Carmona dates the origin to about five millennia ago, which straddles the 3000 BC edge; no independent excavation date fixes -2550 as the start.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('56ba3b1c-2d33-465b-b4d0-85fb987fbdc2'::uuid, 'period_start', '-2550', '-800', 'fields-wd5-2026-10-25p-s004-rollback:56ba3b1c-2d33-465b-b4d0-85fb987fbdc2:period_start', 'rollback of fields-wd5-2026-10-25p-s004: period_start ''-800'' restored on Carmona, Spain', '[{"source": "https://en.wikipedia.org/wiki/History_of_Carmona,_Spain", "url": "https://en.wikipedia.org/wiki/History_of_Carmona,_Spain", "quote": "The first settlement within the limits of present-day Carmona rose about 4500 years ago", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Historia_de_Carmona", "url": "https://es.wikipedia.org/wiki/Historia_de_Carmona", "quote": "el primer poblamiento surgió durante el Calcolítico Pleno, hace aproximadamente 4500 años", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0119)", "decision": "replace", "status": "MISSING", "reasoning": "The history article on Carmona (English and Spanish versions) dates the first settlement within the limits of the present town to about 4500 years ago, in the full Chalcolithic (1950 minus 4500 = -2550), with Chalcolithic remains at the Alcazar, Barranquillo and Picacho; the Museo de la Ciudad de Carmona likewise begins the town''s story in the Chalcolithic. The mid-8th century BC date of the stored -800 only marks the later ''stable core population'' of the Tartessian period, not the start. -2550 lies in the 3000 - 1500 BC bucket, not the stored 1500 - 500 BC. The Spanish article on the town also says ''more than 5000 years'', a looser statement for the area; the specific figure for the town itself is used.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0007", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "The history article is internally inconsistent (first settlement about 4500 years ago in the body, nearly five thousand years of continuous occupation in the lead) and the Museo de la Ciudad de Carmona dates the origin to about five millennia ago, which straddles the 3000 BC edge; no independent excavation date fixes -2550 as the start.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('5b9668cf-d08f-4877-ab48-c4f3b47f5117'::uuid, 'period_name', '3000 - 1500 BC', '1 - 500 AD', 'fields-wd5-2026-10-25p-s004-rollback:5b9668cf-d08f-4877-ab48-c4f3b47f5117:period_name', 'rollback of fields-wd5-2026-10-25p-s004: period_name ''1 - 500 AD'' restored on Bribir, Šibenik-Knin County', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2500) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "The Varvaria-Breberium-Bribir project''s chronology page says that, although life flourished in the Bribir area since the Early Neolithic (the Krivace settlement by the Bribircica rivulet), the hilltop Bribirska Glavica, the archaeological site itself, was settled only from the Bronze Age, when the first fort was built; so the site''s start is the Bronze Age, not 1 AD (the Roman municipium).", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0002", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "The quote is hedged (''it seems'') and dates only the hilltop, while the same page says the Bribir area was settled since the Early Neolithic (Krivace); hr.wikipedia says the Glavica was settled by the Eneolithic and Bronze Age yet at the latest from the start of the 1st millennium BC, and the 2005 Croatian Medical Journal article says Iron Age. Sources disagree on the start phase, so -2500 is not decided.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('5b9668cf-d08f-4877-ab48-c4f3b47f5117'::uuid, 'period_start', '-2500', '1', 'fields-wd5-2026-10-25p-s004-rollback:5b9668cf-d08f-4877-ab48-c4f3b47f5117:period_start', 'rollback of fields-wd5-2026-10-25p-s004: period_start ''1'' restored on Bribir, Šibenik-Knin County', '[{"source": "https://varvaria-breberium-bribir.mf.no/?page_id=369", "url": "https://varvaria-breberium-bribir.mf.no/?page_id=369", "quote": "it seems that the Bribir hilltop (Bribirska Glavica) itself has been settled only from the Bronze Age", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "The Varvaria-Breberium-Bribir project''s chronology page says that, although life flourished in the Bribir area since the Early Neolithic (the Krivace settlement by the Bribircica rivulet), the hilltop Bribirska Glavica, the archaeological site itself, was settled only from the Bronze Age, when the first fort was built; so the site''s start is the Bronze Age, not 1 AD (the Roman municipium).", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0002", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "The quote is hedged (''it seems'') and dates only the hilltop, while the same page says the Bribir area was settled since the Early Neolithic (Krivace); hr.wikipedia says the Glavica was settled by the Eneolithic and Bronze Age yet at the latest from the start of the 1st millennium BC, and the 2005 Croatian Medical Journal article says Iron Age. Sources disagree on the start phase, so -2500 is not decided.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('6582c043-0113-4fb9-a3d3-d3a2b0820a53'::uuid, 'period_name', '1000 - 1500 AD', '1 - 500 AD', 'fields-wd5-2026-10-25p-s004-rollback:6582c043-0113-4fb9-a3d3-d3a2b0820a53:period_name', 'rollback of fields-wd5-2026-10-25p-s004: period_name ''1 - 500 AD'' restored on Puna Pau', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1250) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0008)", "decision": "replace", "status": "MISSING", "reasoning": "The MoeVarua page on Puna Pau (Rapa Nui, Chile) says Puna Pau is the only place on the island where red scoria was quarried to carve the pukao, and that these were carved between 1250 and 1500, so quarrying at the site starts about AD 1250. Other readable sources are vaguer and differ slightly (Imagina Rapa Nui: intense extraction in the 14th to 17th centuries; Wikipedia''s Pukao: made from the 15th to 16th centuries), but all put the start in the 1000-1500 AD band; the stored 1 AD (a band edge) is unsupported.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0001", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "Only a tour-operator page (MoeVarua) says the pukao were carved between 1250 and 1500, with no primary source. Imagina Rapa Nui, reporting the latest excavations, places the intense extraction at Puna Pau in the 14th to 17th centuries, and Wikipedia''s Pukao has them made from the 15th-16th centuries; no excavation report dating the first quarrying was reachable. The sources disagree and AD 1250 is not established as the start of the quarry.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
